local config = {
  ui_story_40120001_1_dialog_content = "Berdasarkan situasi yang dijelaskan di atas, pelakunya adalah salah satu dari tiga orang: Philyshy, Charon, dan Vice.",
  ui_story_40120001_2_dialog_content = "Kita undang Vivian untuk memberikan keterangan tentang kejadian yang terjadi pada hari itu.",
  ui_story_40120001_3_dialog_content = "(A-apa yang kulakukan di sini? Aku tidak paham apa yang terjadi! Ada yang bisa jelaskan?)",
  ui_story_40120001_4_dialog_content = "(Mereka membuat pengadilan sementara di sini. Nemesis dan Vivian mengundangku datang.)",
  ui_story_40120001_5_dialog_content = "(Aku bilang \"diundang\", tapi sebenarnya aku tidak diberi pilihan...)",
  ui_story_40120001_6_dialog_content = "(Mereka bilang kemampuan psikisku akan membantu mereka menemukan pelakunya lebih cepat, jadi aku dipaksa ke sini.)",
  ui_story_40120001_7_dialog_content = "<size=45><color=#e8d9bb>Brak!</color></size>",
  ui_story_40120001_8_dialog_content = "<size=45>Semuanya, tolong dengarkan dengan cermat keterangan Vivian!</size>",
  ui_story_40120001_9_dialog_content = "Ini mungkin kasus pengadilan sementara, tapi kita tetap wajib menanganinya dengan rasa hormat dan keseriusan!",
  ui_story_40120001_10_dialog_content = "Kalau tidak...",
  ui_story_40120001_11_dialog_content = "<color=#e8d9bb>Krak, krak.</color>",
  ui_story_40120001_12_dialog_content = "(Sebaiknya aku serius. Aku tidak mau berakhir seperti cangkir itu...)",
  ui_story_40120001_13_dialog_content = "Hari itu...",
  ui_story_40120001_14_dialog_content = "Sekitar pukul 14.20, aku menyelesaikan pekerjaanku hari itu agar bisa menikmati \"Afternoon Delight Set\" yang baru kuterima...",
  ui_story_40120001_15_dialog_content = "(Memikirkannya saja, perutku sakit... Terakhir, Vivian membiarkanku memakan sebagian besarnya...)",
  ui_story_40120001_16_dialog_content = "Lalu, Charon datang membawa manifes pengiriman, dan kami pergi bersama tidak lama kemudian.",
  ui_story_40120001_17_dialog_content = "Waktu itu, sekitar pukul 14.30.",
  ui_story_40120001_18_dialog_content = "Tolong jelaskan lokasi dan kondisi persisnya dari \"Afternoon Delight Set\" itu saat kamu meninggalkan kantor.",
  ui_story_40120001_19_dialog_content = "Hmm... Posisinya di atas mejaku.",
  ui_story_40120001_20_dialog_content = "Ada kapucino di cangkir kopi, dan empat kue kecil di satu piring. Piring yang satunya berisi puding.",
  ui_story_40120001_21_dialog_content = "(Puding itu terbuat dari <color=#FFB400>keju</color>, kalau aku tidak salah ingat.)",
  ui_story_40120001_22_dialog_content = "Ada penutup kaca dan dua label, masing-masing bertuliskan \"Prize\" dan \"Vivian\".",
  ui_story_40120001_23_dialog_content = "Terus jelaskan kejadian setelahnya.",
  ui_story_40120001_24_dialog_content = "Pada sekitar pukul 15.00, aku bertemu dengan General Inspector dalam perjalanan kembali ke kantor.",
  ui_story_40120001_25_dialog_content = "Aku dapat memberikan kesaksian tentang ini. Waktunya pukul 15.02 persis.",
  ui_story_40120001_26_dialog_content = "Dan itulah saat aku mengetahui bahwa seseorang telah memakan makananku! Yang tersisa hanyalah piring dan cangkir, semuanya kosong!",
  ui_story_40120001_27_dialog_content = "(Aku belum pernah melihat Vivian semarah ini... Pantas dia bersikap agak aneh sebelumnya...)",
  ui_story_40120001_28_dialog_content = "Mmm. Aku juga bisa memberikan kesaksian tentang ini. Ada kemungkinan petunjuk lain?",
  ui_story_40120001_29_dialog_content = "Aku menemukan label \"Prize\" di dalam tempat sampah, masih utuh.",
  ui_story_40120001_30_dialog_content = "Namun, label \"Vivian\" telah disobek menjadi dua.",
  ui_story_40120001_31_dialog_content = "Bagian yang tinggal bertuliskan \"Vi-\" menempel di bibir tempat sampah.",
  ui_story_40120001_32_dialog_content = "Bagian lain, bertuliskan \"-vian\", telah diremas menjadi bola dan dilempar ke dalam tempat sampah.",
  ui_story_40120001_33_dialog_content = "Terakhir, di luar jendela... Seseorang telah melempar pudingku keluar! Tak bisa dimaafkan!!!",
  ui_story_40120001_34_dialog_content = "C-Chief, tenanglah...",
  ui_story_40120001_35_dialog_content = "Meong... Chief memang menakutkan...",
  ui_story_40120001_36_dialog_content = "Emm, maaf... Aku hilang kendali tadi. Pokoknya, seperti itulah kira-kira kejadiannya.",
  ui_story_40120001_37_dialog_content = "Menurut penyelidikanku, satu-satunya yang masuk atau keluar dari kantor antara pukul 14.30 dan 15.00...",
  ui_story_40120001_38_dialog_content = "Dengarkan baik-baik, kalian! Philyshy, Charon, dan Vice! Pelakunya ada di antara kalian!",
  ui_story_40120001_39_dialog_content = "Tidak mungkin, aku tidak ingat apa pun soal itu!",
  ui_story_40120001_40_dialog_content = "(Ada yang aneh dengan raut wajahnya... Apa karena <color=#FFB400>sesuatu</color> di set itu?",
  ui_story_40120001_41_dialog_content = "Puding? Kue? Apa aku terlihat seperti orang yang suka makan makanan seperti itu?! Orang seperti aku, yang sudah pernah menghadapi banyak cobaan...",
  ui_story_40120001_42_dialog_content = "(Dia mungkin tidak suka manis, tapi ada juga <color=#FFB400>sesuatu</color> di set...)",
  ui_story_40120001_43_dialog_content = "Aku sedang diet belakangan ini! Tidak mungkin aku makan yang seperti itu, apalagi sebanyak itu!",
  ui_story_40120001_44_dialog_content = "(Tunggu, satu-satunya alasan Vice diet adalah agar dia bisa makan lebih banyak sesuatu... Seperti <color=#FFB400>sesuatu</color> di set itu!)",
  ui_story_40120001_45_dialog_content = "Cukup. Aku tahu kalian bertiga telah melihat \"Afternoon Delight Set\" itu.",
  ui_story_40120001_46_dialog_content = "Suatu kali, aku pernah meminta orang untuk mengantar penutup kaca, piring, dan cangkir kopi kepada masing-masing dari kalian. Saat itu, ada sedikit perubahan di raut wajah kalian.",
  ui_story_40120001_47_dialog_content = "Apa itu benar, PlayerName?",
  ui_story_40120001_48_dialog_content = "Hmm... Benar juga. Aku ingat wajah Vice sedikit berubah warna saat melihat benda-benda itu.",
  ui_story_40120001_49_dialog_content = "PlayerName... Tak usah menambahi...",
  ui_story_40120001_50_dialog_content = "Baiklah, PlayerName, menimbang kesaksian yang baru saja diberikan, mana tersangka yang menurutmu paling mungkin bersalah?",
  ui_story_40120001_51_option_content = "Philyshy?",
  ui_story_40120001_52_dialog_content = "Kamu juga terlihat sedikit aneh... Mungkin kau menyembunyikan sesuatu dari kami?",
  ui_story_40120001_53_dialog_content = "Jawab pertanyaannya, Philyshy.",
  ui_story_40120001_54_dialog_content = "Bukan aku pelakunya, sumpah! Lagi pula, ada <color=#FFB400>sesuatu</color> di set pencuci mulut itu, dan aku benci benda itu!",
  ui_story_40120001_55_dialog_content = "Dia sepertinya mengatakan yang sebenarnya, General Inspector.",
  ui_story_40120001_56_option_content = "Lalu... Apakah Charon?",
  ui_story_40120001_63_dialog_content = "Oh, begitu...",
  ui_story_40120001_64_dialog_content = "Kamu yang makan kue itu, 'kan? Vice?",
  ui_story_40120001_78_dialog_content = "Yang tersisa tinggal... kamu, Charon.",
  ui_story_40120001_80_dialog_content = "Tapi kamu mulai suka dengan <color=#FFB400>sesuatu</color> itu, dan kebetulan sejak sekitar sebulan yang lalu juga...",
  ui_story_40120001_83_dialog_content = "I-itu benar, tapi yang kuambil dari hidangan itu hanyalah <color=#FFB400>cappuccino</color>!",
  ui_story_40120001_87_dialog_content = "Bagaimana bisa? Puding dan kue? Aku tidak peduli dengan makanan seperti itu!",
  ui_story_40120001_88_dialog_content = "Tapi kamu mulai suka dengan <color=#FFB400>sesuatu</color> itu, dan kebetulan sejak sekitar sebulan yang lalu juga...",
  ui_story_40120001_89_dialog_content = "Ah, itu...",
  ui_story_40120001_90_dialog_content = "Katakan yang sebenarnya. KAMU adalah orang yang meminum kapucino dari set pada hari itu.",
  ui_story_40120001_91_dialog_content = "I-itu benar, tapi yang kuambil dari set itu hanyalah <color=#FFB400>kapucino</color>!",
  ui_story_40120001_92_dialog_content = "Saat masuk ke kantor itu, aku tidak melihat label apa pun. Yang kulihat hanyalah piring kosong, penutup kaca, dan kapucino, jadi kuminum saja...",
  ui_story_40120001_93_dialog_content = "Oh, begitu...",
  ui_story_40120001_94_option_content = "Philyshy, apa Charon mengatakan yang sebenarnya?",
  ui_story_40120001_95_dialog_content = "Bagaimana mungkin aku tahu?",
  ui_story_40120001_96_dialog_content = "Kamu juga terlihat sedikit aneh... Mungkin kamu menyembunyikan sesuatu dari kami?",
  ui_story_40120001_97_dialog_content = "Philyshy! Kamu sungguh tidak menyentuh Afternoon Delight Set itu sebelum Charon masuk ke kantor?",
  ui_story_40120001_100_dialog_content = "Kalau begitu... Tinggal satu orang terakhir yang harus ditanyai...",
  ui_story_40120001_101_dialog_content = "Kamu yang makan kue itu, 'kan? Vice? Aku ingat waktu itu, setelah kita berolahraga bersama...",
  ui_story_40120001_106_dialog_content = "Itu masuk akal, mengingat Vice percaya bahwa makanan manis adalah hadiah yang pantas setelah diet...",
  ui_story_40120001_107_dialog_content = "Maaf.",
  ui_story_40120001_108_option_content = "Kamu yang makan kue itu, 'kan? Vice?",
  ui_story_40120001_109_dialog_content = "Vice!",
  ui_story_40120001_115_dialog_content = "Kalau begitu, tinggal kamu, Philyshy...",
  ui_story_40120001_118_dialog_content = "Philyshy, kamu yakin bahkan tidak melihat Afternoon Delight Set itu pada hari itu?",
  ui_story_40120001_119_dialog_content = "Bukan aku pelakunya, sumpah! Lagi pula, ada <color=#FFB400>sesuatu</color> di set pencuci mulut itu, dan aku benci benda itu!",
  ui_story_40120001_120_dialog_content = "Dia sepertinya mengatakan yang sebenarnya, General Inspector.",
  ui_story_40120001_123_dialog_content = "A-aku akan mengaku! Aku yang makan kuenya, tapi tidak yang lain!",
  ui_story_40120001_124_dialog_content = "Tapi saat aku di sana, satu-satunya yang ada di dalam penutup kaca adalah kue. Labelnya masih ada, bertuliskan \"Prize\" dan \"Vi-\".",
  ui_story_40120001_125_dialog_content = "Walau aku sedang diet waktu itu, kupikir itu hadiah untukku, jadi aku memakannya...",
  ui_story_40120001_128_option_content = "Apa kamu melakukan sesuatu pada Afternoon Delight Set itu, Philyshy?",
  ui_story_40120001_129_dialog_content = "A-aku tidak pernah melihatnya! Aku bahkan tidak tahu seperti apa bentuknya!",
  ui_story_40120001_130_dialog_content = "Kamu juga terlihat sedikit aneh... Mungkin kamu menyembunyikan sesuatu dari kami?",
  ui_story_40120001_134_dialog_content = "Kalau begitu, tinggal kamu... Charon.",
  ui_story_40120001_135_dialog_content = "Kamu yakin? Tapi Vice dan Philyshy-lah yang memakan hampir semuanya!",
  ui_story_40120001_136_dialog_content = "Kemungkinan salah satu dari merekalah yang menghabiskan sisanya, 'kan?",
  ui_story_40120001_137_dialog_content = "Kita belum bisa memastikan, terutama karena kamu mulai suka dengan <color=#FFB400>sesuatu</color> itu, dan kebetulan sejak sekitar sebulan yang lalu juga...",
  ui_story_40120001_138_dialog_content = "Ah, itu...",
  ui_story_40120001_139_dialog_content = "Katakan yang sebenarnya. KAMU adalah orang yang meminum kapucino dari set pada hari itu.",
  ui_story_40120001_141_dialog_content = "Saat masuk ke kantor itu, yang kulihat hanyalah piring kosong, penutup kaca, dan kapucino. Jadi, kuminum saja...",
  ui_story_40120001_142_option_content = "Lalu... Apakah Charon?",
  ui_story_40120001_143_dialog_content = "Aku mengerti... Karena Vice bersalah, kurasa tidak ada alasan untuk mencurigai yang lain... termasuk aku.",
  ui_story_40120001_144_dialog_content = "Tapi kamu mulai suka dengan sesuatu itu, dan kebetulan sejak sekitar sebulan yang lalu juga...",
  ui_story_40120001_148_dialog_content = "Saat masuk ke kantor itu, aku tidak melihat label apa pun. Yang kulihat hanyalah piring kosong, penutup kaca, dan kapucino, jadi kuminum saja...",
  ui_story_40120001_150_dialog_content = "Kalau begitu, tinggal kamu, Philyshy...",
  ui_story_40120001_156_dialog_content = "Kapan kalian datang ke TKP?",
  ui_story_40120001_157_dialog_content = "Aku sama sekali tidak tahu... Bisa kita hentikan pengadilan ini sekarang? Otakku sudah sangat panas...",
  ui_story_40120001_158_dialog_content = "Aku tidak memakai jam tangan hari itu, jadi aku tidak ingat.",
  ui_story_40120001_159_dialog_content = "A-aku tidak memperhatikan waktu. Aku langsung pergi setelah menyantap kue itu...",
  ui_story_40120001_160_dialog_content = "Tanpa kronologi peristiwa yang akurat, kita tidak bisa mengusut kasus ini lebih jauh...",
  ui_story_40120001_161_dialog_content = "Luar biasa... Mereka semua adalah pelaku! Mereka semua bersalah!",
  ui_story_40120001_162_dialog_content = "Tiga bulan! Eh, setengah tahun! Aku akan membuat kalian dikenai pengawasan kinerja selama setengah tahun!",
  ui_story_40120001_163_dialog_content = "Dia cuma sedang marah saja... Percayalah, aku akan membuat keputusan yang adil di kasus ini.",
  ui_story_40120001_164_dialog_content = "Sepertinya mereka semua <color=#FFB400>mengatakan yang sebenarnya</color>.",
  ui_story_40120001_165_dialog_content = "Tolong jelaskan.",
  ui_story_40120001_166_dialog_content = "Mungkin... Semua kesaksian mereka benar!",
  ui_story_40120001_167_dialog_content = "Semuanya benar?",
  ui_story_40120001_168_dialog_content = "Ya... Tapi aku harus mengonfirmasi sesuatu dengan Philyshy dulu.",
  ui_story_40120001_169_dialog_content = "Zzzz... Zzzz...",
  ui_story_40120001_170_dialog_content = "Sepertinya salah satu tersangka tertidur.",
  ui_story_40120001_171_dialog_content = "Tidak, \"dia\" akan bangun sebentar lagi.",
  ui_story_40120001_172_dialog_content = "Hm? Banyak sekali orang... Hari apa ini? Apa aku melewatkan sesuatu?",
  ui_story_40120001_173_dialog_content = "(Yumi datang... Ini mungkin kesempatan kami untuk <color=#FFB400>memecahkan kasus ini</color>!)",
  ui_story_40120001_174_dialog_content = "Halo, Yumi. Kau masih ingat Afternoon Delight Set dari beberapa waktu lalu itu?",
  ui_story_40120001_175_dialog_content = "Maksudmu kudapan-kudapan di atas meja kantor Vivian? Tentu ingat!",
  ui_story_40120001_176_dialog_content = "Yumi! Jadi, kamu pelakunya?!",
  ui_story_40120001_177_dialog_content = "Kamu bicara apa? Saat Philyshy masuk ke kantor, dia bahkan tidak melihat nampan berisi kudapan itu.",
  ui_story_40120001_178_dialog_content = "Dia juga tidak tidur siang, jadi tertidur tidak lama setelah itu.",
  ui_story_40120001_179_dialog_content = "Lalu, seperti biasa... Giliranku untuk keluar!",
  ui_story_40120001_180_dialog_content = "Tapi tidak kuduga, puding yang hancur itu ada di hadapanku saat aku bangun!",
  ui_story_40120001_181_dialog_content = "Hanya ada satu orang di dunia yang menganggap keju sebagai musuh... Dan itu kamu, Yumi!",
  ui_story_40120001_182_dialog_content = "Tapi, aku melakukan satu-satunya tindakan yang masuk akal dalam situasi itu—aku membuka paksa penutup kaca dan membuang puding itu ke luar jendela!",
  ui_story_40120001_183_dialog_content = "Lalu?",
  ui_story_40120001_184_dialog_content = "Lalu... Aku menyobek label itu dan membersihkan tangan...",
  ui_story_40120001_185_dialog_content = "Label yang mana?",
  ui_story_40120001_186_dialog_content = "*Menguap*... Jam berapa ini...",
  ui_story_40120001_187_dialog_content = "Intel Chief Yumi, jangan sekali-kali tertidur! Kita belum selesai!",
  ui_story_40120001_188_dialog_content = "Label itu... Aku membuangnya... ke tempat sampah...",
  ui_story_40120001_189_dialog_content = "Lalu aku mengambil... penutup ka...",
  ui_story_40120001_190_dialog_content = "Kapucino... Zzzz...",
  ui_story_40120001_191_dialog_content = "Apa... kita bisa memakai pernyataan ambigu seperti itu sebagai kesaksian?",
  ui_story_40120001_192_dialog_content = "Tidak penting lagi, biarkan dia tidur. Kupikir... Aku akhirnya memahami kasus ini.",
  ui_story_40120001_193_dialog_content = "Benarkah?",
  ui_story_40120001_194_dialog_content = "Kalau begitu, jelaskan! Apa yang sebenarnya terjadi hari itu?",
  ui_story_40120001_195_dialog_content = "*Mengambil napas panjang*",
  ui_story_40120001_196_option_content = "Kupikir yang pertama adalah Philyshy.",
  ui_story_40120001_197_dialog_content = "Yang kedua...",
  ui_story_40120001_198_option_content = "Charon?",
  ui_story_40120001_200_dialog_content = "Benar, yang artinya Charon adalah orang ketiga yang masuk ke kantor... Aku paham sekarang.",
  ui_story_40120001_202_option_content = "Vice?",
  ui_story_40120001_203_dialog_content = "Masuk akal. Apa yang terjadi kemudian?",
  ui_story_40120001_204_dialog_content = "Kalau begitu, kita harus kembali ke Philyshy.",
  ui_story_40120001_205_option_content = "Pelakunya Vice, bukan?",
  ui_story_40120001_206_dialog_content = "Itu tidak mungkin! Bagaimana kau akan menjelaskan label itu? Saat aku masuk ke kantor, label itu sudah disobek!",
  ui_story_40120001_207_dialog_content = "Kamu tidak salah... Vice seharusnya orang kedua yang masuk ke kantor.",
  ui_story_40120001_208_option_content = "Kalau begitu, yang pertama adalah Charon?",
  ui_story_40120001_210_dialog_content = "Ah, salah lagi... Aku benar-benar harus menangani ini dengan serius...",
  ui_story_40120001_211_dialog_content = "Kalau begitu, tinggal satu orang. Yang pertama masuk ke kantor adalah Philyshy.",
  ui_story_40120001_212_option_content = "Orang pertama yang masuk adalah Philyshy.",
  ui_story_40120001_213_option_content = "Kupikir, Charon yang pertama?",
  ui_story_40120001_214_dialog_content = "Tapi itu tidak menjelaskan apa yang terjadi pada kue dan puding itu! Saat aku di sana, yang tersisa hanyalah kapucino.",
  ui_story_40120001_215_dialog_content = "Sama sekali tidak benar... Coba lagi!",
  ui_story_40120001_216_option_content = "Kalau begitu seharusnya Vice!",
  ui_story_40120001_217_dialog_content = "Tapi PlayerName... Saat aku masuk ke kantor, labelnya sudah disobek...",
  ui_story_40120001_218_dialog_content = "Philyshy. Maksudku Philyshy.",
  ui_story_40120001_219_option_content = "Menurutku orang pertama yang masuk ke kantor adalah Philyshy.",
  ui_story_40120001_220_dialog_content = "Tapi karena belum tidur siang, Philyshy tidur sepanjang waktu.",
  ui_story_40120001_221_dialog_content = "Sementara Yumi, yang baru saja bangun, terkejut melihat puding keju itu, dan langsung melemparnya ke luar jendela.",
  ui_story_40120001_222_dialog_content = "Setelah itu, dia menyobek setengah dari label yang bertuliskan \"Vivian\" dan menggunakannya untuk mengelap tangan, lalu membuangnya ke tempat sampah.",
  ui_story_40120001_223_dialog_content = "Itu menjelaskan kenapa bagian label yang bertuliskan \"Vi-\" masih ada di penutup kaca.",
  ui_story_40120001_224_dialog_content = "Setelah itu, karena alasan yang hanya diketahui oleh para kucing, dia menempatkan penutup itu di atas kue, tanpa menyentuh kapucino.",
  ui_story_40120001_225_dialog_content = "Ke... Keju... Semoga semua keju musnah...",
  ui_story_40120001_226_dialog_content = "Ini menghasilkan anggapan yang salah dari tersangka berikutnya yang masuk ke kantor—",
  ui_story_40120001_227_dialog_content = "Vice.",
  ui_story_40120001_228_dialog_content = "Saat dia melihat kue favoritnya di meja dan penutup dengan label yang bertuliskan \"Vi-\"...",
  ui_story_40120001_229_dialog_content = "Dia berasumsi bahwa itu hadiahnya karena sudah diet.",
  ui_story_40120001_230_dialog_content = "Jadi, dia dengan senang hati memakannya dan membuang labelnya ke tempat sampah. Bukan begitu, Vice?",
  ui_story_40120001_231_dialog_content = "M-mengagumkan... Persis seperti itulah yang terjadi...",
  ui_story_40120001_232_dialog_content = "Artinya, orang terakhir yang masuk ke TKP... adalah Charon.",
  ui_story_40120001_233_dialog_content = "Apa yang dilihatnya saat dia masuk? Piring kosong, penutup kaca, dan kapucino yang telah disisihkan.",
  ui_story_40120001_234_dialog_content = "Mungkin karena mengira itu boleh diminum siapa saja, dia mengambil dan meminumnya sendiri.",
  ui_story_40120001_235_dialog_content = "Lalu, sekitar pukul 15.00, atau tidak lama setelah dia pergi... Nemesis dan Vivian kembali ke TKP bersama-sama.",
  ui_story_40120001_236_dialog_content = "Pada saat itu, piring dan cangkirnya sudah kosong, labelnya di tempat sampah, dan puding yang malang itu berantakan di tanah luar jendela.",
  ui_story_40120001_237_dialog_content = "Sebuah kisah tragis tentang kesalahpahaman, tuduhan, keserakahan tak terkendali, dan nasib sial. Begitulah semua ini.",
  ui_story_40120001_238_dialog_content = "...",
  ui_story_40120001_239_dialog_content = "Kesimpulannya, Philyshy, Charon, dan Vice memikul tanggung jawab yang setara atas kejahatan ini. Kasus ditutup.",
  ui_story_40120001_240_dialog_content = "Ketiganya bersalah, tapi juga tidak bersalah...",
  ui_story_40120001_241_dialog_content = "Aku mengerti. Fakta ini memang mengherankan, tapi aku merasa lega.",
  ui_story_40120001_242_dialog_content = "Kalau kita tidak menguak faktanya hari ini, aku pasti akan merasa tidak tenang karena ada pencuri di antara kita.",
  ui_story_40120001_243_dialog_content = "Aku juga ingin meminta maaf atas sikapku yang emosional tadi. Reaksiku sungguh tidak pantas...",
  ui_story_40120001_244_dialog_content = "Tapi kalian semua tahu! Aku berencana menikmati pencuci mulut itu segera setelah menyelesaikan pekerjaan hari itu!",
  ui_story_40120001_245_dialog_content = "Satu hal yang aku sangat tidak suka, yaitu saat rencanaku berantakan!",
  ui_story_40120001_246_dialog_content = "Aku paham, Chief... Kami tidak sepenuhnya tidak bersalah, dan untuk itu kami minta maaf...",
  ui_story_40120001_247_dialog_content = "Setelah sesuatu yang berharga diambil darimu... Kamu pantas marah. Bagaimana kami bisa menebus kesalahan ini?",
  ui_story_40120001_248_dialog_content = "Bagaimana kalau kita pesan satu set baru?",
  ui_story_40120001_249_dialog_content = "Sepertinya kamu belum cukup makan hari itu, PlayerName.",
  ui_story_40120001_250_dialog_content = "Bahkan kalau kita memesan lagi, Vivian tidak akan merasakan hal yang sama dengan hari itu.",
  ui_story_40120001_251_dialog_content = "Kepuasan dari duduk di kursinya yang nyaman setelah seharian bekerja, dan menikmati gigitan pertama...",
  ui_story_40120001_252_dialog_content = "Ah! Omong-omong soal pekerjaan!",
  ui_story_40120001_253_dialog_content = "Oh, tidak...",
  ui_story_40120001_254_dialog_content = "Hah?",
  ui_story_40120001_255_dialog_content = "Sekarang setelah pengadilan sementara ini dibubarkan, kita perlu orang untuk mengelola, merangkum, dan mencatat sidang hari ini.",
  ui_story_40120001_256_dialog_content = "Selain itu, seseorang harus membawa Philyshy kembali ke Living Quarters.",
  ui_story_40120001_257_dialog_content = "Dan sebagai hadiahnya... Bagaimana kalau Hidangan Santai Sore Hari? Kita perlu orang untuk membuatnya juga.",
  ui_story_40120001_258_dialog_content = "Sekarang... Nemesis, Vice, Charon, Navigator...",
  ui_story_40120001_259_dialog_content = "Tugas-tugas sudah kita sebutkan, sekarang semua orang hanya perlu—",
  ui_story_40120001_260_dialog_content = "K-kamu sudah kembali normal, Chief!",
  ui_story_40120001_261_dialog_content = "Boleh aku minta waktu istirahat sebentar? Otakku lelah setelah semua ini...",
  ui_story_40120001_262_dialog_content = "Kalian semua mendengar Chief! Kalau tidak ada keberatan lagi—",
  ui_story_40120001_263_dialog_content = "Kasus ditutup! Sidang dibubarkan! Sekarang kembali bekerja, kalian semua!",
  ui_story_40120001_264_dialog_content = "Apa ada yang mendengarku?!"
}
